Revoke Consent > API /consents/{consentId}/action/revoke

  "source_path": "/consents/{consentId}/action/revoke",
  "operations": {
    "post": {
      "tags": [
        "actions"
      ],
      "summary": "Revoke a consent by its id",
      "description": "Revokes a consent by its id along with any associated access and refresh tokens.\nThis API is used by ozone internally to revoke consents.\nThe API should be used by a financial institution to revoke consents (rather than simply patching the consent) to also revoke the tokens associated with the consent",
      "operationId": "revokeConsentsByConsentId",
      "parameters": [
        {
          "$ref": "#/components/parameters/consentId"
        }
      ],
      "requestBody": {
        "description": "An end-point for revoking a consent.\n",
        "required": true,
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/RevokeConsent"
            }
          }
        }
      },
      "responses": {
        "204": {
          "description": "Indicates a successful operation.\nThe response does not have a body.\n"
        },
        "400": {
          "description": "Indicates a failure to revoke the consent\n",
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/error400Response"
              }
            }
          }
        }
      }
    }
  },
  "security": [
    {},
    {
      "OzoneConnectJwtAuth": []
    }
  ],
  "securitySchemes": {
    "OzoneConnectJwtAuth": {
      "description": "Communications between the API Hub and the LFI Ozone Connect implementation are secured using the \"JWT Auth\" mechanism, where the Client presents a signed JSON Web Token as a credential.\n\nThe Server MUST verify the signature in order to authenticate the Client.\n\nPlease note that the value of the `scheme` parameter is not a registered HTTP Authentication Scheme, to indicate it is specific to Ozone Connect. Please refer to API Hub documentation for further details.\n",
      "type": "http",
      "scheme": "Ozone-Connect-JWT-Auth"
    }
  }
}

